import * as THREE from 'three/webgpu';
import gsap from 'gsap';

// Default export function for Badge for Pricing
export default function createNode(config, ctx) {
  // 1. Create geometry (simple plane, capsule shape achieved via texture alpha)
  const width = 1.0;
  const height = 0.4;
  const geometry = new THREE.PlaneGeometry(width, height);

  // 2. Load texture from imageUrl (cached by ctx.textureLoader)
  const textureUrl = config.assets?.imageUrl || '/prism-assets/chrome/ceramic-grain.map.png';
  const texture = ctx.textureLoader.load(textureUrl);
  texture.colorSpace = THREE.SRGBColorSpace;

  // 3. Create material (MeshBasicNodeMaterial – no lighting, rely on texture for accent edge)
  const material = new THREE.MeshBasicNodeMaterial({
    map: texture,
    transparent: true,
    side: THREE.DoubleSide,
    depthWrite: true,
  });

  // 4. Build the mesh
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(config.scenePosition?.x ?? 1.25, config.scenePosition?.y ?? 0.7, config.scenePosition?.z ?? 0);
  mesh.rotation.set(config.sceneRotation?.x ?? 0, config.sceneRotation?.y ?? 0, config.sceneRotation?.z ?? 0);
  mesh.scale.set(config.sceneScale?.x ?? 1, config.sceneScale?.y ?? 1, config.sceneScale?.z ?? 1);

  // 5. UserData setup
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    if (mesh.userData._hoverTimeline) {
      mesh.userData._hoverTimeline.kill();
    }
  };

  // 6. Interaction handlers
  mesh.userData.handlers = {
    // Hover: subtle rise-in animation (preset: rise-in, 0.15 scene units)
    pointerenter: () => {
      if (mesh.userData._hoverTimeline) mesh.userData._hoverTimeline.kill();
      mesh.userData._hoverTimeline = gsap.to(mesh.position, {
        y: mesh.position.y + 0.15,
        duration: 0.7,
        ease: 'power3.out',
        overwrite: 'auto',
      });
    },
    pointerleave: () => {
      if (mesh.userData._hoverTimeline) mesh.userData._hoverTimeline.kill();
      mesh.userData._hoverTimeline = gsap.to(mesh.position, {
        y: mesh.position.y, // revert to original y (stored in closure)
        duration: 0.5,
        ease: 'power2.out',
        overwrite: 'auto',
      });
    },
    // Click: emit event (hub-pricing.select)
    click: () => {
      // Use ctx.emit if available, else log
      if (typeof ctx.emit === 'function') {
        ctx.emit('hub-pricing.select');
      } else {
        console.log('Event emitted: hub-pricing.select');
      }
    },
  };

  // Store original y for leave animation (capture in closure)
  const originalY = mesh.position.y;
  // Override leave closure to use originalY
  mesh.userData.handlers.pointerleave = () => {
    if (mesh.userData._hoverTimeline) mesh.userData._hoverTimeline.kill();
    mesh.userData._hoverTimeline = gsap.to(mesh.position, {
      y: originalY,
      duration: 0.5,
      ease: 'power2.out',
      overwrite: 'auto',
    });
  };

  return mesh;
}
